begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select plan(18);
select ok(not has_table_privilege('anon','public.consultation_anthropometry','select'),'anonymous cannot read anthropometry');
select ok(not has_table_privilege('authenticated','public.consultation_anthropometry','update'),'no update grants on history');
select ok(not has_table_privilege('authenticated','public.consultation_anthropometry','delete'),'no delete grants on history');
insert into auth.users(id,email) values
 ('a1000000-0000-4000-8000-000000000001','anthro-owner@nuthrick.test'),
 ('a2000000-0000-4000-8000-000000000002','anthro-other@nuthrick.test');
set local role authenticated;
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);
select is((select show_formula_guidance from public.professional_profiles where id=auth.uid()),true,'guidance defaults to enabled');
insert into public.patients(id,full_name) values ('a3000000-0000-4000-8000-000000000003','Anthropometry fixture'),('a4000000-0000-4000-8000-000000000004','Other fixture');
select public.start_consultation_draft('a3000000-0000-4000-8000-000000000003','initial');
select set_config('test.anthro_consultation',(select id::text from public.consultations where patient_id='a3000000-0000-4000-8000-000000000003'),true);
select lives_ok($$insert into public.consultation_anthropometry(patient_id,consultation_id,revision,measured_at,payload) values ('a3000000-0000-4000-8000-000000000003',current_setting('test.anthro_consultation')::uuid,1,'2026-09-03T12:00:00Z','{"schemaVersion":1,"engineVersion":"1.0.0","input":{"measuredAt":"2026-09-03T12:00:00Z","bia":{},"measurements":{}},"results":[{"value":26.122448979591837,"method":"IMC","classification":"Sobrepeso","reference_id":"who-adult-bmi","reference_version":"2000-v1"}],"assessment":[],"note":"","noteReviewed":false,"diagnosis":{"enabled":false}}'::jsonb)$$,'owner appends first assessment');
select throws_ok($$insert into public.consultation_anthropometry(patient_id,consultation_id,revision,measured_at,payload) values ('a3000000-0000-4000-8000-000000000003',current_setting('test.anthro_consultation')::uuid,2,'2026-09-03T12:00:00Z','{"schemaVersion":1,"engineVersion":"1.0.0","input":{"measuredAt":"2026-09-03T12:00:00Z","bia":{},"measurements":{}},"results":[{"value":26.122448979591837,"method":"IMC","classification":"Sobrepeso","reference_id":"who-adult-bmi","reference_version":"2000-v1"}],"assessment":[],"note":"","noteReviewed":false,"diagnosis":{"enabled":false}}'::jsonb || '{"note":"not reviewed"}'::jsonb)$$,'P0001','Review the note before saving','unreviewed note rejected');
select throws_ok($$insert into public.consultation_anthropometry(patient_id,consultation_id,revision,measured_at,payload) values ('a4000000-0000-4000-8000-000000000004',current_setting('test.anthro_consultation')::uuid,2,'2026-09-03T12:00:00Z','{"schemaVersion":1,"engineVersion":"1.0.0","input":{"measuredAt":"2026-09-03T12:00:00Z","bia":{},"measurements":{}},"results":[{"value":26.122448979591837,"method":"IMC","classification":"Sobrepeso","reference_id":"who-adult-bmi","reference_version":"2000-v1"}],"assessment":[],"note":"","noteReviewed":false,"diagnosis":{"enabled":false}}'::jsonb)$$,'42501','Only an owned draft can be saved','patient must match consultation');
select throws_ok($$insert into public.consultation_anthropometry(patient_id,consultation_id,revision,measured_at,payload) values ('a3000000-0000-4000-8000-000000000003',current_setting('test.anthro_consultation')::uuid,1,'2026-09-03T12:00:00Z','{"schemaVersion":1,"engineVersion":"1.0.0","input":{"measuredAt":"2026-09-03T12:00:00Z","bia":{},"measurements":{}},"results":[{"value":26.122448979591837,"method":"IMC","classification":"Sobrepeso","reference_id":"who-adult-bmi","reference_version":"2000-v1"}],"assessment":[],"note":"","noteReviewed":false,"diagnosis":{"enabled":false}}'::jsonb)$$,'P0001','Revision changed. Reload before saving.','stale writer rejected');
select lives_ok($$insert into public.consultation_anthropometry(patient_id,consultation_id,revision,measured_at,payload) values ('a3000000-0000-4000-8000-000000000003',current_setting('test.anthro_consultation')::uuid,2,'2026-09-03T12:00:00Z','{"schemaVersion":1,"engineVersion":"1.0.0","input":{"measuredAt":"2026-09-03T12:00:00Z","bia":{},"measurements":{}},"results":[{"value":26.122448979591837,"method":"IMC","classification":"Sobrepeso","reference_id":"who-adult-bmi","reference_version":"2000-v1"}],"assessment":[],"note":"","noteReviewed":false,"diagnosis":{"enabled":false}}'::jsonb || '{"note":"Professional reviewed note","noteReviewed":true}'::jsonb)$$,'reviewed note appended');
select is((select count(*) from public.consultation_anthropometry),2::bigint,'both revisions retained');
select is((select payload from public.consultation_anthropometry where revision=1),'{"schemaVersion":1,"engineVersion":"1.0.0","input":{"measuredAt":"2026-09-03T12:00:00Z","bia":{},"measurements":{}},"results":[{"value":26.122448979591837,"method":"IMC","classification":"Sobrepeso","reference_id":"who-adult-bmi","reference_version":"2000-v1"}],"assessment":[],"note":"","noteReviewed":false,"diagnosis":{"enabled":false}}'::jsonb,'original exact values and reference remain unchanged');
select throws_ok($$update public.consultation_anthropometry set payload='{}' where revision=1$$,'42501','permission denied for table consultation_anthropometry','cannot rewrite stored revision');
select throws_ok($$delete from public.consultation_anthropometry where revision=1$$,'42501','permission denied for table consultation_anthropometry','cannot delete individual revision');
select set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000002',true);
select is((select count(*) from public.consultation_anthropometry),0::bigint,'second professional sees no other records');
select throws_ok($$insert into public.consultation_anthropometry(patient_id,consultation_id,revision,measured_at,payload) values ('a3000000-0000-4000-8000-000000000003',current_setting('test.anthro_consultation')::uuid,3,'2026-09-03T12:00:00Z','{"schemaVersion":1,"engineVersion":"1.0.0","input":{"measuredAt":"2026-09-03T12:00:00Z","bia":{},"measurements":{}},"results":[{"value":26.122448979591837,"method":"IMC","classification":"Sobrepeso","reference_id":"who-adult-bmi","reference_version":"2000-v1"}],"assessment":[],"note":"","noteReviewed":false,"diagnosis":{"enabled":false}}'::jsonb)$$,'42501','Only an owned draft can be saved','second professional cannot insert into another consultation');
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);
select throws_ok($$insert into public.consultation_anthropometry(patient_id,consultation_id,revision,measured_at,payload) values ('a3000000-0000-4000-8000-000000000003',current_setting('test.anthro_consultation')::uuid,3,'2026-09-03T12:00:00Z','{}'::jsonb)$$,'23514',null,'empty document rejected');
update public.consultations set status='completed',completed_at=now() where id=current_setting('test.anthro_consultation')::uuid;
select throws_ok($$insert into public.consultation_anthropometry(patient_id,consultation_id,revision,measured_at,payload) values ('a3000000-0000-4000-8000-000000000003',current_setting('test.anthro_consultation')::uuid,3,'2026-09-03T12:00:00Z','{"schemaVersion":1,"engineVersion":"1.0.0","input":{"measuredAt":"2026-09-03T12:00:00Z","bia":{},"measurements":{}},"results":[{"value":26.122448979591837,"method":"IMC","classification":"Sobrepeso","reference_id":"who-adult-bmi","reference_version":"2000-v1"}],"assessment":[],"note":"","noteReviewed":false,"diagnosis":{"enabled":false}}'::jsonb)$$,'42501','Only an owned draft can be saved','closed consultation cannot accept new revisions');
select is((select payload->>'note' from public.consultation_anthropometry where revision=2),'Professional reviewed note','closed history retains reviewed note');
select * from finish();
rollback;
